/*
 * Sortable scoreboard tables.
 *
 * The tables are generated by evaluation/scoreboard.py inside
 * `<div class="scoreboard">`. Sortable header cells carry `data-col` (index of
 * their column in the body) and, for metrics, `data-best` ("asc" or "desc": the
 * direction that puts the best values first). Body cells carry the exact,
 * unrounded values: `data-sort` (Type column) or `data-values` (one value per
 * test, separated by ";", empty if missing). The table's `data-tests` lists the
 * test names, in the order of the values.
 *
 * Clicking a metric cycles through the tests, always with the best values
 * first: test 1, test 2, ... Clicking Type toggles between the
 * generated order (grouped by type, alphabetical within a type) and the types
 * in reverse order. Missing values always go last, and ties keep the
 * generated order.
 */

function setupScoreboard(table) {
  if (table.dataset.sortReady) return;  // already set up on this page
  table.dataset.sortReady = "true";

  const body = table.tBodies[0];
  const rows = Array.from(body.rows);
  rows.forEach((row, index) => { row.dataset.order = index; });
  const tests = (table.dataset.tests || "").split(";");
  const headers = Array.from(table.querySelectorAll("th.sortable"));
  let active = null;  // header currently sorting the table
  let step = 0;       // position in the click cycle of the active header

  // value of a row for a column and test (NaN if missing)
  function value(row, col, test) {
    const cell = row.cells[col];
    const raw = test === null
      ? cell.dataset.sort
      : (cell.dataset.values || "").split(";")[test];
    return raw === undefined || raw === "" ? NaN : Number(raw);
  }

  function sort(col, test, descending) {
    const sorted = rows.slice().sort((a, b) => {
      const va = value(a, col, test);
      const vb = value(b, col, test);
      if (Number.isNaN(va) !== Number.isNaN(vb)) return Number.isNaN(va) ? 1 : -1;
      if (!Number.isNaN(va) && va !== vb) return descending ? vb - va : va - vb;
      return a.dataset.order - b.dataset.order;  // ties: generated order
    });
    sorted.forEach((row) => body.appendChild(row));
  }

  // show which header sorts the table, by which test and in which direction
  function mark(header, text, title) {
    headers.forEach((h) => {
      h.removeAttribute("data-sorted");
      h.removeAttribute("aria-sort");
      h.title = "Click to sort";
    });
    if (header) {
      header.dataset.sorted = text;
      header.title = title;
    }
  }

  headers.forEach((header) => {
    header.title = "Click to sort";
    header.addEventListener("click", () => {
      step = header === active ? step + 1 : 0;
      active = header;
      const col = Number(header.dataset.col);

      if (!header.dataset.best) {  // Type column: generated order or reversed
        const reversed = step % 2 === 1;
        sort(col, null, reversed);
        mark(header, reversed ? "▼" : "▲",
          reversed ? "Types in reverse order" : "Grouped by type");
        return;
      }

      // metric: best values first, cycling through the tests
      step %= tests.length;
      const test = step;
      const ascending = header.dataset.best === "asc";
      sort(col, test, !ascending);
      mark(header, `${ascending ? "▲" : "▼"}${test + 1}`,
        `Sorted by ${tests[test]}, best first. Click again to change.`);
      header.setAttribute("aria-sort", ascending ? "ascending" : "descending");
    });
  });
}

function setupScoreboards() {
  document.querySelectorAll(".scoreboard table").forEach(setupScoreboard);
}

// `document$` is the theme's page-load signal (it also fires after instant
// navigation); fall back to the plain browser event otherwise
if (typeof document$ !== "undefined") {
  document$.subscribe(setupScoreboards);
} else {
  document.addEventListener("DOMContentLoaded", setupScoreboards);
}
